// Scaffolding generated by `dart run drift_dev make-migrations`; the
// data-integrity tests below are hand-written. Add a test per new version.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fundly/core/database/app_database.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v10.dart' as v10;
import 'generated/schema_v2.dart' as v2;
import 'generated/schema_v3.dart' as v3;
import 'generated/schema_v4.dart' as v4;
import 'generated/schema_v5.dart' as v5;
import 'generated/schema_v6.dart' as v6;
import 'generated/schema_v7.dart' as v7;
import 'generated/schema_v8.dart' as v8;
import 'generated/schema_v9.dart' as v9;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // Verifies every possible upgrade produces exactly the saved schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('v1 to v2 keeps accounts unchanged and seeds categories', () async {
    const accounts = [
      v1.AccountsData(
        id: 1,
        name: 'BDO Savings',
        type: 'savingsCash',
        openingBalanceMinor: 1500000,
        currencyCode: 'PHP',
        createdAt: '2026-11-16T09:30:00.000Z',
        isArchived: 0,
      ),
      v1.AccountsData(
        id: 2,
        name: 'RCBC Credit',
        type: 'credit',
        openingBalanceMinor: -300000,
        currencyCode: 'PHP',
        createdAt: '2026-11-16T09:31:00.000Z',
        isArchived: 1,
      ),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) => batch.insertAll(oldDb.accounts, accounts),
      validateItems: (newDb) async {
        final migratedAccounts = await newDb.select(newDb.accounts).get();
        expect(
          migratedAccounts.map((row) => row.toJson()).toList(),
          accounts.map((row) => row.toJson()).toList(),
        );

        final categories = await (newDb.select(
          newDb.categories,
        )..orderBy([(c) => OrderingTerm(expression: c.id)])).get();
        expect(categories.map((c) => (c.name, c.kind)).toList(), [
          ('Food', 'spending'),
          ('Transport', 'spending'),
          ('Utilities', 'spending'),
          ('Subscriptions', 'spending'),
          ('Shopping', 'spending'),
          ('Health', 'spending'),
          ('Other', 'spending'),
          ('Salary', 'inflow'),
          ('Other income', 'inflow'),
        ]);
      },
    );
  });

  group('to v3 keeps accounts and categories; transactions start empty', () {
    const account = v1.AccountsData(
      id: 1,
      name: 'BDO Savings',
      type: 'savingsCash',
      openingBalanceMinor: 1500000,
      currencyCode: 'PHP',
      createdAt: '2026-11-16T09:30:00.000Z',
      isArchived: 0,
    );

    Future<void> validateV3(v3.DatabaseAtV3 db) async {
      final accounts = await db.select(db.accounts).get();
      expect(accounts.map((row) => row.toJson()).toList(), [account.toJson()]);
      expect(await db.select(db.categories).get(), hasLength(9));
      expect(await db.select(db.transactions).get(), isEmpty);
    }

    test('from v2', () async {
      await verifier.testWithDataIntegrity(
        oldVersion: 2,
        newVersion: 3,
        createOld: v2.DatabaseAtV2.new,
        createNew: v3.DatabaseAtV3.new,
        openTestedDatabase: AppDatabase.new,
        createItems: (batch, oldDb) {
          batch.insert(
            oldDb.accounts,
            v2.AccountsData.fromJson(account.toJson()),
          );
          // v2 databases already hold the seeded categories.
          batch.insertAll(oldDb.categories, [
            for (final (i, (name, kind)) in const [
              ('Food', 'spending'),
              ('Transport', 'spending'),
              ('Utilities', 'spending'),
              ('Subscriptions', 'spending'),
              ('Shopping', 'spending'),
              ('Health', 'spending'),
              ('Other', 'spending'),
              ('Salary', 'inflow'),
              ('Other income', 'inflow'),
            ].indexed)
              v2.CategoriesData(id: i + 1, name: name, kind: kind),
          ]);
        },
        validateItems: validateV3,
      );
    });

    test('from v1 in one step', () async {
      await verifier.testWithDataIntegrity(
        oldVersion: 1,
        newVersion: 3,
        createOld: v1.DatabaseAtV1.new,
        createNew: v3.DatabaseAtV3.new,
        openTestedDatabase: AppDatabase.new,
        createItems: (batch, oldDb) => batch.insert(oldDb.accounts, account),
        validateItems: validateV3,
      );
    });
  });

  test('v3 to v4 keeps categories and transactions; none archived', () async {
    const account = v3.AccountsData(
      id: 1,
      name: 'BDO Savings',
      type: 'savingsCash',
      openingBalanceMinor: 1500000,
      currencyCode: 'PHP',
      createdAt: '2026-11-16T09:30:00.000Z',
      isArchived: 0,
    );
    const categories = [
      v3.CategoriesData(id: 1, name: 'Food', kind: 'spending'),
      v3.CategoriesData(id: 2, name: 'Salary', kind: 'inflow'),
    ];
    const transaction = v3.TransactionsData(
      id: 1,
      type: 'spending',
      amountMinor: 50000,
      currencyCode: 'PHP',
      date: '2026-11-16',
      payee: 'SM Supermarket',
      categoryId: 1,
      sourceAccountId: 1,
      note: '',
      createdAt: '2026-11-16T10:00:00.000Z',
      updatedAt: '2026-11-16T10:00:00.000Z',
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 3,
      newVersion: 4,
      createOld: v3.DatabaseAtV3.new,
      createNew: v4.DatabaseAtV4.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insert(oldDb.accounts, account)
          ..insertAll(oldDb.categories, categories)
          ..insert(oldDb.transactions, transaction);
      },
      validateItems: (newDb) async {
        final migrated = await (newDb.select(
          newDb.categories,
        )..orderBy([(c) => OrderingTerm(expression: c.id)])).get();
        expect(migrated, const [
          v4.CategoriesData(
            id: 1,
            name: 'Food',
            kind: 'spending',
            isArchived: 0,
          ),
          v4.CategoriesData(
            id: 2,
            name: 'Salary',
            kind: 'inflow',
            isArchived: 0,
          ),
        ]);

        final transactions = await newDb.select(newDb.transactions).get();
        expect(transactions.map((row) => row.toJson()).toList(), [
          transaction.toJson(),
        ]);
        final accounts = await newDb.select(newDb.accounts).get();
        expect(accounts.map((row) => row.toJson()).toList(), [
          account.toJson(),
        ]);
      },
    );
  });

  group('to v5 keeps existing data; monthly plans start empty', () {
    const account = v1.AccountsData(
      id: 1,
      name: 'BDO Savings',
      type: 'savingsCash',
      openingBalanceMinor: 1500000,
      currencyCode: 'PHP',
      createdAt: '2026-11-16T09:30:00.000Z',
      isArchived: 0,
    );

    test('from v4', () async {
      const categories = [
        v4.CategoriesData(id: 1, name: 'Food', kind: 'spending', isArchived: 0),
        v4.CategoriesData(
          id: 2,
          name: 'Gifts',
          kind: 'spending',
          isArchived: 1,
        ),
      ];
      const transaction = v4.TransactionsData(
        id: 1,
        type: 'spending',
        amountMinor: 50000,
        currencyCode: 'PHP',
        date: '2026-11-16',
        payee: 'SM Supermarket',
        categoryId: 1,
        sourceAccountId: 1,
        note: '',
        createdAt: '2026-11-16T10:00:00.000Z',
        updatedAt: '2026-11-16T10:00:00.000Z',
      );

      await verifier.testWithDataIntegrity(
        oldVersion: 4,
        newVersion: 5,
        createOld: v4.DatabaseAtV4.new,
        createNew: v5.DatabaseAtV5.new,
        openTestedDatabase: AppDatabase.new,
        createItems: (batch, oldDb) {
          batch
            ..insert(oldDb.accounts, v4.AccountsData.fromJson(account.toJson()))
            ..insertAll(oldDb.categories, categories)
            ..insert(oldDb.transactions, transaction);
        },
        validateItems: (newDb) async {
          final accounts = await newDb.select(newDb.accounts).get();
          expect(accounts.map((row) => row.toJson()).toList(), [
            account.toJson(),
          ]);
          final migratedCategories = await newDb.select(newDb.categories).get();
          expect(
            migratedCategories.map((row) => row.toJson()).toList(),
            categories.map((row) => row.toJson()).toList(),
          );
          final transactions = await newDb.select(newDb.transactions).get();
          expect(transactions.map((row) => row.toJson()).toList(), [
            transaction.toJson(),
          ]);
          expect(await newDb.select(newDb.monthlyPlans).get(), isEmpty);
        },
      );
    });

    test('from v1 in one step', () async {
      await verifier.testWithDataIntegrity(
        oldVersion: 1,
        newVersion: 5,
        createOld: v1.DatabaseAtV1.new,
        createNew: v5.DatabaseAtV5.new,
        openTestedDatabase: AppDatabase.new,
        createItems: (batch, oldDb) => batch.insert(oldDb.accounts, account),
        validateItems: (newDb) async {
          final accounts = await newDb.select(newDb.accounts).get();
          expect(accounts.map((row) => row.toJson()).toList(), [
            account.toJson(),
          ]);
          expect(await newDb.select(newDb.categories).get(), hasLength(9));
          expect(await newDb.select(newDb.monthlyPlans).get(), isEmpty);
        },
      );
    });
  });

  group('v5 to v6: planned amounts become both target and assigned', () {
    const categories = [
      v5.CategoriesData(id: 1, name: 'Food', kind: 'spending', isArchived: 0),
      v5.CategoriesData(id: 2, name: 'Gifts', kind: 'spending', isArchived: 1),
    ];
    const plans = [
      v5.MonthlyPlansData(
        id: 1,
        month: '2026-11',
        categoryId: 1,
        plannedAmountMinor: 500000,
        currencyCode: 'PHP',
        createdAt: '2026-11-16T09:00:00.000Z',
        updatedAt: '2026-11-16T10:00:00.000Z',
      ),
      // Zero stays a zero target, not "no target".
      v5.MonthlyPlansData(
        id: 2,
        month: '2026-11',
        categoryId: 2,
        plannedAmountMinor: 0,
        currencyCode: 'PHP',
        createdAt: '2026-11-16T09:00:00.000Z',
        updatedAt: '2026-11-16T09:00:00.000Z',
      ),
      v5.MonthlyPlansData(
        id: 3,
        month: '2026-12',
        categoryId: 1,
        plannedAmountMinor: 300050,
        currencyCode: 'PHP',
        createdAt: '2026-11-17T08:00:00.000Z',
        updatedAt: '2026-11-17T08:00:00.000Z',
      ),
    ];
    const transaction = v5.TransactionsData(
      id: 1,
      type: 'spending',
      amountMinor: 50000,
      currencyCode: 'PHP',
      date: '2026-11-16',
      payee: 'SM Supermarket',
      categoryId: 1,
      sourceAccountId: 1,
      note: '',
      createdAt: '2026-11-16T10:00:00.000Z',
      updatedAt: '2026-11-16T10:00:00.000Z',
    );
    const account = v5.AccountsData(
      id: 1,
      name: 'BDO Savings',
      type: 'savingsCash',
      openingBalanceMinor: 1500000,
      currencyCode: 'PHP',
      createdAt: '2026-11-16T09:30:00.000Z',
      isArchived: 0,
    );

    test('keeps every plan and the rest of the data', () async {
      await verifier.testWithDataIntegrity(
        oldVersion: 5,
        newVersion: 6,
        createOld: v5.DatabaseAtV5.new,
        createNew: v6.DatabaseAtV6.new,
        openTestedDatabase: AppDatabase.new,
        createItems: (batch, oldDb) {
          batch
            ..insert(oldDb.accounts, account)
            ..insertAll(oldDb.categories, categories)
            ..insert(oldDb.transactions, transaction)
            ..insertAll(oldDb.monthlyPlans, plans);
        },
        validateItems: (newDb) async {
          final migrated = await newDb.select(newDb.monthlyPlans).get();
          expect(migrated, [
            for (final plan in plans)
              v6.MonthlyPlansData(
                id: plan.id,
                month: plan.month,
                categoryId: plan.categoryId,
                targetAmountMinor: plan.plannedAmountMinor,
                assignedAmountMinor: plan.plannedAmountMinor,
                currencyCode: plan.currencyCode,
                createdAt: plan.createdAt,
                updatedAt: plan.updatedAt,
              ),
          ]);
          expect(
            (await newDb.select(newDb.accounts).get()).map((r) => r.toJson()),
            [account.toJson()],
          );
          expect(
            (await newDb.select(newDb.categories).get()).map((r) => r.toJson()),
            categories.map((r) => r.toJson()),
          );
          expect(
            (await newDb.select(newDb.transactions).get()).map(
              (r) => r.toJson(),
            ),
            [transaction.toJson()],
          );

          // The rebuilt table still enforces its rules.
          Future<void> insert(Object? target, int assigned) =>
              newDb.customStatement(
                'INSERT INTO monthly_plans (month, category_id, '
                'target_amount_minor, assigned_amount_minor, currency_code, '
                'created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
                [
                  '2027-01',
                  1,
                  target,
                  assigned,
                  'PHP',
                  '2026-11-17T08:00:00.000Z',
                  '2026-11-17T08:00:00.000Z',
                ],
              );
          await expectLater(insert(-1, 0), throwsA(isA<Exception>()));
          await expectLater(insert(0, -1), throwsA(isA<Exception>()));
          await insert(null, 100);
          await expectLater(insert(null, 100), throwsA(isA<Exception>()));
        },
      );
    });
  });

  test('v6 to v7 keeps every account with no custom type', () async {
    const accounts = [
      v6.AccountsData(
        id: 1,
        name: 'BDO Savings',
        type: 'savingsCash',
        openingBalanceMinor: 1500000,
        currencyCode: 'PHP',
        createdAt: '2026-11-16T09:30:00.000Z',
        isArchived: 0,
      ),
      v6.AccountsData(
        id: 2,
        name: 'RCBC Credit',
        type: 'credit',
        openingBalanceMinor: -300000,
        currencyCode: 'PHP',
        createdAt: '2026-11-16T09:31:00.000Z',
        isArchived: 1,
      ),
    ];
    const category = v6.CategoriesData(
      id: 1,
      name: 'Food',
      kind: 'spending',
      isArchived: 0,
    );
    const transaction = v6.TransactionsData(
      id: 1,
      type: 'spending',
      amountMinor: 50000,
      currencyCode: 'PHP',
      date: '2026-11-16',
      payee: 'SM Supermarket',
      categoryId: 1,
      sourceAccountId: 2,
      note: '',
      createdAt: '2026-11-16T10:00:00.000Z',
      updatedAt: '2026-11-16T10:00:00.000Z',
    );
    const plan = v6.MonthlyPlansData(
      id: 1,
      month: '2026-11',
      categoryId: 1,
      targetAmountMinor: 500000,
      assignedAmountMinor: 250000,
      currencyCode: 'PHP',
      createdAt: '2026-11-16T09:00:00.000Z',
      updatedAt: '2026-11-16T09:00:00.000Z',
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 6,
      newVersion: 7,
      createOld: v6.DatabaseAtV6.new,
      createNew: v7.DatabaseAtV7.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insertAll(oldDb.accounts, accounts)
          ..insert(oldDb.categories, category)
          ..insert(oldDb.transactions, transaction)
          ..insert(oldDb.monthlyPlans, plan);
      },
      validateItems: (newDb) async {
        final migrated = await (newDb.select(
          newDb.accounts,
        )..orderBy([(a) => OrderingTerm(expression: a.id)])).get();
        expect(migrated, [
          for (final account in accounts)
            v7.AccountsData(
              id: account.id,
              name: account.name,
              type: account.type,
              openingBalanceMinor: account.openingBalanceMinor,
              currencyCode: account.currencyCode,
              createdAt: account.createdAt,
              isArchived: account.isArchived,
            ),
        ]);
        expect(await newDb.select(newDb.customAccountTypes).get(), isEmpty);
        expect(
          (await newDb.select(newDb.categories).get()).map((r) => r.toJson()),
          [category.toJson()],
        );
        expect(
          (await newDb.select(newDb.transactions).get()).map((r) => r.toJson()),
          [transaction.toJson()],
        );
        expect(
          (await newDb.select(newDb.monthlyPlans).get()).map((r) => r.toJson()),
          [plan.toJson()],
        );

        // The new column links to an existing custom type only.
        await newDb.customStatement('PRAGMA foreign_keys = ON');
        await expectLater(
          newDb.customStatement(
            'UPDATE accounts SET custom_type_id = 99 WHERE id = 1',
          ),
          throwsA(isA<Exception>()),
        );
        await newDb.customStatement(
          'INSERT INTO custom_account_types (id, name, base_type, created_at) '
          "VALUES (1, 'E-wallet', 'savingsCash', '2026-11-17T08:00:00.000Z')",
        );
        await newDb.customStatement(
          'UPDATE accounts SET custom_type_id = 1 WHERE id = 1',
        );
      },
    );
  });

